            entries.append(
                "\n".join((
                    "  <url>",
                    f"    <loc>{loc}</loc>",
                    f"    <lastmod>{lastmod}</lastmod>",
                    "  </url>",
                ))
            )
        body = "\n".join((
            '<?xml version="1.0" encoding="UTF-8"?>',
            '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">',
            *entries,
            "</urlset>",
            "",
        ))
        resp = Response(body, mimetype="application/xml")
        resp.headers["Cache-Control"] = JOB_PAGE_CACHE
        return resp

